// Des: CLI glue for the local browser: session, actions, login
// Flo: expand profile dir (+ account name) > Rndr or none > read steps file under the step cap > login = headed Chrome until the owner closes it
// I/O: Ctx (caller) > Rndr / Acts; login prints one status line; owner types credentials by hand, scra never sees them
// ===================================================================
const std = @import("std"); const erru = @import("er-erro-type.zig"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const rend = @import("nt-brow-rend.zig"); const actz = @import("nt-brow-acts.zig"); const chro = @import("nt-brow-chro.zig"); const pexp = @import("ut-path-expa.zig"); const acct = @import("ru-acct-guar.zig"); const site = @import("cf-site-rule.zig"); const pipe = @import("ru-page-fetc.zig");
fn nameOkay(tex2: []const u8) bool { if (tex2.len == 0 or tex2.len > 32) return false; for (tex2) |chr2| { if (!std.ascii.isAlphanumeric(chr2) and chr2 != '-' and chr2 != '_') return false; } return true; }
pub fn profDirz(ctx2: *const ctx3.Ctxz, name: []const u8) ![]const u8 { const base = if (ctx2.conf.brow_prof_dirz.len == 0) try std.fs.path.join(ctx2.allo, &.{ ctx2.dirz, "prof" }) else pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.brow_prof_dirz) catch return error.BadConfig; if (name.len == 0) return base; if (!nameOkay(name)) return erru.usag("bad account name", name); return std.fs.path.join(ctx2.allo, &.{ base, name }); }
pub fn brwzMake(ctx2: *const ctx3.Ctxz, name: []const u8) !?rend.Rndr { if (!ctx2.conf.brow_enab and !site.siteTrue(ctx2.conf, "brow_enab")) return null; return try rend.rndrInit(ctx2.init.gpa, ctx2.iozz, ctx2.conf, try profDirz(ctx2, name)); }
pub fn actsOfzz(ctx2: *const ctx3.Ctxz) !actz.Acts { var acts: actz.Acts = .{ .scrl = ctx2.args.scrl, .clic = ctx2.args.clic, .cons = ctx2.args.cons }; if (ctx2.args.ste2.len > 0) { const tex2 = std.Io.Dir.cwd().readFileAlloc(ctx2.iozz, ctx2.args.ste2, ctx2.allo, .limited(1 << 20)) catch return erru.usag("cannot read --steps file", ctx2.args.ste2); acts.ste2 = try actz.stepRead(ctx2.allo, tex2, ctx2.conf.brow_step_maxz); } return acts; }
pub fn runzLogi(ctx2: *const ctx3.Ctxz) !u8 { const name = ctx2.args.urlz; if (!ctx2.conf.logi_mode_enab or !ctx2.conf.brow_enab) return error.NotConfigured; if (!nameOkay(name)) return erru.usag("bad account name", name); const exe2 = (try chro.exezFind(ctx2.init.gpa, ctx2.iozz, ctx2.conf.brow_path_exec)) orelse return error.NoBrowser; defer ctx2.init.gpa.free(exe2); const prof = try profDirz(ctx2, name); var brwz = try chro.laun(ctx2.init.gpa, ctx2.iozz, exe2, prof, false, .{ .widt = ctx2.conf.brow_wind_widt, .high = ctx2.conf.brow_wind_high, .scal = ctx2.conf.brow_wind_scal, .left = ctx2.conf.brow_wind_left }, 30000); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "login '{s}': a browser window is open. Log in by hand, then close the window. scra never sees what you type.", .{name})); while (!chro.portDead(ctx2.init.gpa, ctx2.iozz, brwz.port)) std.Io.sleep(ctx2.iozz, .fromMilliseconds(1000), .awake) catch {}; brwz.stop(); var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); try acct.acctClea(&dbzz, name); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "login '{s}': session saved. Use: sc-scra fetch <url> --live --account {s}", .{ name, name })); _ = pipe.nowzMill; return 0; }
